type version = V20 | V26 | V26Par

type info = {
  info_syn        : syntax_map;
  info_rliteral   : syntax_map;
  mutable info_model : S.t;
  mutable info_in_goal : bool;
  info_vc_term : vc_term_info;
  info_printer : ident_printer;
  mutable type_coercions : Sls.t Mty.t;
  mutable type_fields : (lsymbol list) Mty.t;
  mutable type_sorts  : tysymbol Mstr.t;
  mutable ty_tysymbol : ty Mts.t;
  info_version : version;
  meta_model_projection : Sls.t;
  meta_record_def : Sls.t;
  mutable record_fields : (lsymbol list) Mls.t;
  mutable constr_proj_id : string list Mls.t;
  mutable constructors: lsymbol Mstr.t;
  info_cntexample_need_push : bool;
  info_cntexample: bool;
  info_incremental: bool;
  info_set_incremental: bool;
  info_supports_reason_unknown : bool;
  info_supports_minimize: bool;
  mutable info_labels: Sattr.t Mstr.t;
  mutable incr_list_axioms: (prsymbol * term) list;
  mutable incr_list_ldecls: (lsymbol * vsymbol list * term) list;
}

let debug_print_term message t =
  let form = Debug.get_debug_formatter () in
  begin
    Debug.dprintf debug message;
    if Debug.test_flag debug then
      Pretty.print_term form t;
    Debug.dprintf debug "@.";
  end

let print_ident info fmt id =
  pp_print_string fmt (id_unique info.info_printer id)

(** type *)

let print_tv info fmt tv =
  pp_print_string fmt (id_unique info.info_printer tv.tv_name)

(** print `(par ...)` around the given body to print *)
let print_par info (* body *) =
  (* Format.kdprintf *) (fun print_body ->
      (fun fmt tvs ->
         if Ty.Stv.is_empty tvs
         then print_body fmt
         else if info.info_version = V26Par
         then
           Format.fprintf fmt "(par (%a)@ %t)"
             (print_iter1 Ty.Stv.iter pp_print_space (print_tv info)) tvs
             print_body
         else
           unsupported "smt: polymorphism must be encoded"
      ) ) (* body *)

let rec print_type info fmt ty = match ty.ty_node with
  | Tyvar s ->
      begin match info.info_version with
      | V20 -> unsupported "smtv2: you must encode type polymorphism"
      | V26 | V26Par -> print_tv info fmt s
      end
  | Tyapp (ts, l) ->
      begin match query_syntax info.info_syn ts.ts_name, l with
      | Some s, _ ->
        info.type_sorts <- Mstr.add s ts info.type_sorts;
        info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol;
        syntax_arguments s (print_type info) fmt l
      | None, [] -> print_ident info fmt ts.ts_name
      | None, _ -> fprintf fmt "(%a %a)" (print_ident info) ts.ts_name
          (print_list space (print_type info)) l
     end

let print_type info fmt ty = try print_type info fmt ty
  with Unsupported s -> raise (UnsupportedType (ty,s))

let print_type_value info fmt = function
  | None -> pp_print_string fmt "Bool"
  | Some ty -> print_type info fmt ty

(** var *)
let forget_var info v = forget_id info.info_printer v.vs_name

let print_var info fmt {vs_name = id} =
  let n = id_unique info.info_printer id in
  pp_print_string fmt n

let print_typed_var info fmt vs =
  fprintf fmt "(%a %a)" (print_var info) vs
    (print_type info) vs.vs_ty

let print_var_list info fmt vsl =
  print_list space (print_var info) fmt vsl

let print_typed_var_list info fmt vsl =
  print_list space (print_typed_var info) fmt vsl

let collect_model_ls info ls =
  if Sls.mem ls info.meta_model_projection then
    begin match ls.ls_args with
    | [ty] ->
      let coercions = Sls.add ls (Mty.find_def Sls.empty ty info.type_coercions) in
      info.type_coercions <- Mty.add ty coercions info.type_coercions
    | _ -> assert false
    end;
  if Sls.mem ls info.meta_record_def then
    begin match ls.ls_args with
    | [ty] ->
      let fields = ls :: (Mty.find_def [] ty info.type_fields) in
      info.type_fields <- Mty.add ty fields info.type_fields
    | _ -> assert false
    end;
  if relevant_for_counterexample ls.ls_name then
    info.info_model <-
      add_model_element (ls, ls.ls_name.id_loc, ls.ls_name.id_attrs) info.info_model

let number_format = {
    Number.long_int_support = `Default;
    Number.negative_int_support = `Default;
    Number.dec_int_support = `Default;
    Number.hex_int_support = `Unsupported;
    Number.oct_int_support = `Unsupported;
    Number.bin_int_support = `Unsupported;
    Number.negative_real_support = `Default;
    Number.dec_real_support = `Unsupported;
    Number.hex_real_support = `Unsupported;
    Number.frac_real_support =
      `Custom
        ((fun fmt i -> fprintf fmt "%s.0" i),
         (fun fmt i n -> fprintf fmt "(/ %s.0 %s.0)" i n));
}

let escape c = match c with
  | '\\'  -> "\\x5C"
  | '\"'  -> "\\x22"
  | '\032' .. '\126' -> Format.sprintf "%c" c
  | '\000' .. '\031'
  | '\127' .. '\255' -> Format.sprintf "\\x%02X" (Char.code c)

(* can the type of a value be derived from the type of the arguments? *)
let unambig_fs version fs =
  let rec lookup v ty = match ty.ty_node with
    | Tyvar u when tv_equal u v -> true
    | _ -> ty_any (lookup v) ty
  in
  let lookup v = List.exists (lookup v) fs.ls_args in
  let rec inspect ty = match ty.ty_node with
    | Tyvar u when not (lookup u) -> false
    | _ -> ty_all inspect ty
  in
  match version with
  | V20 -> true
  | V26 | V26Par ->  inspect (Option.get fs.ls_value)

(** expr *)
let rec print_term info fmt t =
  debug_print_term "Printing term: " t;
  if check_for_counterexample t
  then
    begin match t.t_node with
    | Tapp (ls,_) ->
      info.info_model <- add_model_element (ls,t.t_loc,t.t_attrs) info.info_model
    | _ -> assert false (* cannot happen because check_for_counterexample is true *)
    end;

  begin
   let ty = t.t_ty in
    match ty with
    | None -> ()
    | Some ty ->
      match ty.ty_node with
      | Tyvar _ -> ()
      | Tyapp (ts, _) ->
    info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol
  end;

  check_enter_vc_term t info.info_in_goal info.info_vc_term;

  let () = match t.t_node with
  | Tconst c ->
      let ts = match t.t_ty with
        | Some ({ ty_node = Tyapp (ts, []) } as ty) ->
          info.ty_tysymbol <- Mts.add ts ty info.ty_tysymbol;
          ts
        | _ -> assert false (* impossible *) in
      (* look for syntax literal ts in driver *)
      begin match query_syntax info.info_rliteral ts.ts_name, c with
        | Some st, Constant.ConstInt c ->
          info.type_sorts <- Mstr.add st ts info.type_sorts;
          syntax_range_literal st fmt c
        | Some st, Constant.ConstReal c ->
          info.type_sorts <- Mstr.add st ts info.type_sorts;
          let fp = match ts.ts_def with
            | Float fp -> fp
            | _ -> assert false in
          syntax_float_literal st fp fmt c
        | _, Constant.ConstStr _
        | None, _ ->
            (* we must check here that the type is either ty_int or
               ty_real, otherwise it makes no sense to print the
               literal. This may happen since we can't ensure that
               preserved literal types are exactly those that have a
               dedicated syntax rule *)
            if ts_equal ts ts_int || ts_equal ts ts_real || ts_equal ts ts_str then
              Constant.print number_format escape fmt c
            else
              unsupportedTerm t
                "smtv2: don't know how to print this literal, consider adding a syntax rule in the driver"
      end
  | Tvar v -> print_var info fmt v
  | Tapp (ls, tl) ->
    begin match query_syntax info.info_syn ls.ls_name with
      | Some s -> syntax_arguments_typed s (print_term info)
        (print_type info) t fmt tl
      | None -> begin match tl with (* for cvc3 wich doesn't accept (toto ) *)
          | [] ->

            let str_ls = sprintf "%a" (print_ident info) ls.ls_name in
            let cur_var = info.info_labels in
            let new_var = update_info_labels str_ls cur_var t ls in
            let () = info.info_labels <- new_var in
            let vc_term_info = info.info_vc_term in
            if vc_term_info.vc_inside then begin
              match vc_term_info.vc_loc with
              | None -> ()
              | Some loc ->
                let attrs = (* match vc_term_info.vc_func_name with
                  | None -> *)
                    ls.ls_name.id_attrs
                  (* | Some _ ->
                    model_trace_for_postcondition ~attrs:ls.ls_name.id_attrs info.info_vc_term
                   *)
                in
		let _t_check_pos = t_attr_set ~loc attrs t in
		(* TODO: temporarily disable collecting variables inside the term triggering VC *)
		(*info.info_model <- add_model_element t_check_pos info.info_model;*)
		()
	    end;
            if unambig_fs info.info_version ls then
	      fprintf fmt "@[%a@]" (print_ident info) ls.ls_name
            else
              fprintf fmt "@[(as %a %a)@]" (print_ident info) ls.ls_name
                (print_type info) (t_type t)
          | _ ->
            if unambig_fs info.info_version ls then
	      fprintf fmt "@[<hv2>(%a@ %a)@]"
	        (print_ident info) ls.ls_name
                (print_list space (print_term info)) tl
            else
              fprintf fmt "@[<hv2>((as %a@ %a)@ %a)@]"
                (print_ident info) ls.ls_name
                (print_type info) (t_type t)
                (print_list space (print_term info)) tl
        end
    end
  | Tlet (t1, tb) ->
      let v, t2 = t_open_bound tb in
      fprintf fmt "@[<hv2>(let ((%a %a))@ %a)@]" (print_var info) v
        (print_term info) t1 (print_term info) t2;
      forget_var info v
  | Tif (f1,t1,t2) ->
      fprintf fmt "@[<hv2>(ite %a@ %a@ %a)@]"
        (print_fmla info) f1 (print_term info) t1 (print_term info) t2
  | Tcase(t, bl) ->
     print_tcase info t print_term fmt bl
  | Teps _ -> unsupportedTerm t
      "smtv2: you must eliminate epsilon"
  | Tquant _ | Tbinop _ | Tnot _ | Ttrue | Tfalse -> raise (TermExpected t)
  in

  check_exit_vc_term t info.info_in_goal info.info_vc_term;

and print_fmla info fmt f =
  debug_print_term "Printing formula: " f;
  if check_for_counterexample f
  then
    begin match f.t_node with
    | Tapp (ls,_) ->
      info.info_model <- add_model_element (ls,f.t_loc,f.t_attrs) info.info_model
    | _ -> assert false (* cannot happen because check_for_counterexample is true *)
    end;

  check_enter_vc_term f info.info_in_goal info.info_vc_term;

  let () = match f.t_node with
  | Tapp ({ ls_name = id }, []) ->
      print_ident info fmt id
  | Tapp (ls, tl) -> begin match query_syntax info.info_syn ls.ls_name with
      | Some s -> syntax_arguments_typed s (print_term info)
        (print_type info) f fmt tl
      | None -> begin match tl with (* for cvc3 wich doesn't accept (toto ) *)
          | [] ->
              print_ident info fmt ls.ls_name
          | _ -> fprintf fmt "@[<hv2>(%a@ %a)@]"
              (print_ident info) ls.ls_name
              (print_list space (print_term info)) tl
        end end
  | Tquant (q, fq) ->
      let q = match q with Tforall -> "forall" | Texists -> "exists" in
      let vl, tl, f = t_open_quant fq in
      (* TODO trigger dépend des capacités du prover : 2 printers?
      smtwithtriggers/smtstrict *)
      if tl = [] then
        fprintf fmt "@[<hv2>(%s @[<h>(%a)@]@ %a)@]"
          q
          (print_typed_var_list info) vl
          (print_fmla info) f
      else
        fprintf fmt "@[<hv2>(%s @[<h>(%a)@]@ (! %a %a))@]"
          q
          (print_typed_var_list info) vl
          (print_fmla info) f
          (print_triggers info) tl;
      List.iter (forget_var info) vl
  | Tbinop (Tand, f1, f2) ->
      fprintf fmt "@[<hv2>(and@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
  | Tbinop (Tor, f1, f2) ->
      fprintf fmt "@[<hv2>(or@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
  | Tbinop (Timplies, f1, f2) ->
      fprintf fmt "@[<hv2>(=>@ %a@ %a)@]"
        (print_fmla info) f1 (print_fmla info) f2
  | Tbinop (Tiff, f1, f2) ->
      fprintf fmt "@[<hv2>(=@ %a@ %a)@]" (print_fmla info) f1 (print_fmla info) f2
  | Tnot f ->
      fprintf fmt "@[<hv2>(not@ %a)@]" (print_fmla info) f
  | Ttrue ->
      pp_print_string fmt "true"
  | Tfalse ->
      pp_print_string fmt "false"
  | Tif (f1, f2, f3) ->
      fprintf fmt "@[<hv2>(ite %a@ %a@ %a)@]"
        (print_fmla info) f1 (print_fmla info) f2 (print_fmla info) f3
  | Tlet (t1, tb) ->
      let v, f2 = t_open_bound tb in
      fprintf fmt "@[<hv2>(let ((%a %a))@ %a)@]" (print_var info) v
        (print_term info) t1 (print_fmla info) f2;
      forget_var info v
  | Tcase(t, bl) ->
     print_tcase info t print_fmla fmt bl
  | Tvar _ | Tconst _ | Teps _ -> raise (FmlaExpected f) in

  check_exit_vc_term f info.info_in_goal info.info_vc_term

and print_tcase info t pr fmt bl =
     let ty = t_type t in
     match ty.ty_node with
     | Tyapp (ts,_) when ts_equal ts ts_bool ->
        print_boolean_branches info t pr fmt bl
     | _ ->
        match info.info_version with
        | V20 | V26Par -> begin
            (* Use a chain of if-then-else constructs. *)
            match t.t_node with
            | Tvar v -> print_branches info v pr fmt bl
            | _ ->
               let subject = create_vsymbol (id_fresh "subject") (t_type t) in
               fprintf fmt "@[<hv2>(let ((%a @[%a@]))@ %a)@]"
                 (print_var info) subject (print_term info) t
                 (print_branches info subject pr) bl;
               forget_var info subject
          end
        | V26 ->
           fprintf fmt "@[<hv2>(match %a (@[<hv0>%a@]))@]"
             (print_term info) t
             (print_list space (print_match_branch info ty pr)) bl

and print_match_branch info ty pr fmt b =
  let (p,t) = t_open_branch b in
  let error () = unsupportedPattern p
    "smtv2: you must compile nested pattern-matching" in
  match p.pat_node with
  | Pwild ->
     let wild = create_vsymbol (id_fresh "wildcard") ty in
     fprintf fmt "@[<hv2>(%a %a)@]" (print_var info) wild (pr info) t
  | Papp(cs,[]) ->
     fprintf fmt "@[<hv2>(%a %a)@]" (print_ident info) cs.ls_name (pr info) t;
  | Papp(cs,args) ->
     let args = List.map (function
       | {pat_node = Pvar v} -> v | _ -> error ()) args in
     fprintf fmt "@[<hv2>(@[<hv2>(%a %a)@] %a)@]"
       (print_ident info) cs.ls_name (print_list space (print_var info)) args
       (pr info) t
  | _ -> error ()

and print_boolean_branches info subject pr fmt bl =
  let error () = unsupportedTerm subject
    "smtv2: bad pattern-matching on Boolean (compile_match missing?)"
  in
  match bl with
  | [br1 ; br2] ->
    let (p1,t1) = t_open_branch br1 in
    let (_p2,t2) = t_open_branch br2 in
    begin
      match p1.pat_node with
      | Papp(cs,_) ->
        let t1, t2 = if ls_equal cs fs_bool_true then t1, t2 else t2, t1 in
        fprintf fmt "@[<hv2>(ite %a %a %a)@]"
          (print_term info) subject
          (pr info) t1
          (pr info) t2
      | _ -> error ()
    end
  | _ -> error ()

and print_branches info subject pr fmt bl = match bl with
  | [] -> assert false
  | br::bl ->
      let (p,t) = t_open_branch br in
      let error () = unsupportedPattern p
        "smtv2: you must compile nested pattern-matching" in
      match p.pat_node with
      | Pwild -> pr info fmt t
      | Papp (cs,args) ->
          let args = List.map (function
            | {pat_node = Pvar v} -> v | _ -> error ()) args in
          if bl = [] then print_branch info subject pr fmt (cs,args,t)
          else
            begin match info.info_version with
              | V20 (* It was not defined at that time in the standard *) ->
                  fprintf fmt "@[<hv2>(ite (is-%a %a) %a %a)@]"
              | V26 | V26Par ->
                  fprintf fmt "@[<hv2>(ite ((_ is %a) %a) %a %a)@]"
            end
              (print_ident info) cs.ls_name (print_var info) subject
              (print_branch info subject pr) (cs,args,t)
              (print_branches info subject pr) bl
      | _ -> error ()

and print_branch info subject pr fmt (cs,vars,t) =
  if vars = [] then pr info fmt t else
  let tvs = t_freevars Mvs.empty t in
  if List.for_all (fun v -> not (Mvs.mem v tvs)) vars then pr info fmt t else
  let pr_proj fmt (v, p) =
    if Mvs.mem v tvs then fprintf fmt "(%a (%s %a))"
      (print_var info) v p (print_var info) subject in
  let l = List.combine vars (Mls.find cs info.constr_proj_id) in
  fprintf fmt "@[<hv2>(let (%a) %a)@]" (print_list space pr_proj) l (pr info) t

and print_expr info fmt =
  TermTF.t_select (print_term info fmt) (print_fmla info fmt)

and print_trigger info fmt e =
  print_expr info fmt e

and print_triggers info fmt = function
  | [] -> ()
  | a::l -> fprintf fmt ":pattern (%a) %a"
    (print_list space (print_trigger info)) a
    (print_triggers info) l

let print_type_decl info fmt ts =
  if is_alias_type_def ts.ts_def then () else
  if Mid.mem ts.ts_name info.info_syn then () else
  let sort_name = sprintf "%a" (print_ident info) ts.ts_name in
  info.type_sorts <- Mstr.add sort_name ts info.type_sorts;
  fprintf fmt "(declare-sort %a %i)@\n@\n"
    (print_ident info) ts.ts_name (List.length ts.ts_args)

let print_param_decl info fmt ls =
  if Mid.mem ls.ls_name info.info_syn then () else match ls.ls_args with
    | [] -> fprintf fmt "@[<hov 2>(declare-const %a %a)@]@\n@\n"
              (print_ident info) ls.ls_name
              (print_type_value info) ls.ls_value
    | _  ->
        let tvs = Term.ls_ty_freevars ls in
        fprintf fmt ";; %S@\n@[<v2>(declare-fun %a %a)@]@\n@\n"
          ls.ls_name.id_string (print_ident info) ls.ls_name
          (print_par info
             (fun fmt -> Format.fprintf fmt "(%a) %a"
                 (print_list space (print_type info)) ls.ls_args
                 (print_type_value info) ls.ls_value)) tvs

let rec has_quantification f =
  match f.t_node with
  | Tquant _ | Teps _ -> true
  | _ -> Term.t_any has_quantification f

let print_logic_decl_aux flag info fmt (ls,def) =
  if not (Mid.mem ls.ls_name info.info_syn) then begin
    collect_model_ls info ls;
    let vsl,expr = Decl.open_ls_defn def in
    if info.info_incremental && has_quantification expr then begin
      print_param_decl info fmt ls;
      info.incr_list_ldecls <- (ls, vsl, expr) :: info.incr_list_ldecls
    end else
      let tvs = Term.ls_ty_freevars ls in
      fprintf fmt ";; %S@\n@[<v2>(define-fun%s %a %a)@]@\n@\n"
        ls.ls_name.id_string flag
        (print_ident info) ls.ls_name
        (print_par info
           (fun fmt -> Format.fprintf fmt "@[<h>(%a) %a@]@ %a"
               (print_typed_var_list info) vsl
               (print_type_value info) ls.ls_value
               (print_expr info) expr)) tvs;
      List.iter (forget_var info) vsl
  end

let print_logic_decl = print_logic_decl_aux ""

let print_rec_logic_decl info fmt = function
  | [] -> ()
  | [ld] ->
      print_logic_decl_aux "-rec" info fmt ld
  | l ->
      let l = List.map (fun (ls,def) ->
          let vsl,expr = Decl.open_ls_defn def in
          (ls,vsl,expr)
        ) l
      in
      let print_decl fmt (ls,vsl,_) =
        if Mid.mem ls.ls_name info.info_syn then () else begin
          collect_model_ls info ls;
          let tvs = Term.ls_ty_freevars ls in
          fprintf fmt "@[<hov 2>(%a %a)@]@\n@\n"
            (print_ident info) ls.ls_name
            (print_par info
               (fun fmt -> Format.fprintf fmt "(%a) %a"
                   (print_typed_var_list info) vsl
                   (print_type_value info) ls.ls_value)) tvs;
        end
      in
      let print_term fmt (ls,_,expr) =
        if Mid.mem ls.ls_name info.info_syn then () else begin
          fprintf fmt "@[<hov 2>%a@]"
            (print_expr info) expr
        end
      in
      fprintf fmt "@[<hov 2>(define-funs-rec (%a) (%a))@]@\n@\n"
        (print_list nothing print_decl) l
        (print_list nothing print_term) l;
      List.iter (fun (_,vsl,_) -> List.iter (forget_var info) vsl) l

let print_info_model info =
  (* Prints the content of info.info_model *)
  let info_model = info.info_model in
  if not (S.is_empty info_model) && info.info_cntexample then
    begin
      let model_map =
        S.fold
          (fun ((ls,oloc,attrs) as el) acc ->
            let s = asprintf "%a" (print_ident info) ls.ls_name in
            try
              (* We keep the location attribute of every equal terms that were
                 collected during printing in order to provide a complete
                 counterexample. *)
              let (_,_,attrs') = Mstr.find s acc in
              let attrs' = Sattr.union attrs attrs' in
              let attrs' =
                if oloc <> None then
                  Sattr.add (Ident.create_written_attr (Option.get oloc)) attrs'
                else
                  attrs' in
              Mstr.add s (ls,oloc,attrs') acc
            with Not_found -> Mstr.add s el acc)
          info_model
          Mstr.empty in ();

        (* Printing model has modification of info.info_model as undesirable
        side-effect. Revert it back. *)
        info.info_model <- info_model;
        model_map
    end
  else
    Mstr.empty


(* TODO factor out print_prop ? *)
let print_prop info fmt (pr, f) =
  let tvs = Term.t_ty_freevars Ty.Stv.empty f in
  fprintf fmt ";; %S@\n@[<hov 2>(assert@ %a)@]@\n@\n"
    pr.pr_name.id_string (* FIXME? collisions *)
    (print_par info (fun fmt -> print_fmla info fmt f)) tvs

let add_check_sat info fmt =
  if info.info_cntexample && info.info_cntexample_need_push then
    fprintf fmt "@[(push)@]@\n";
  fprintf fmt "@[(check-sat)@]@\n";
  if info.info_supports_reason_unknown then
    fprintf fmt "@[(get-info :reason-unknown)@]@\n";
  if info.info_cntexample then
    fprintf fmt "@[(get-model)@]@\n@\n"

let print_ldecl_axiom info fmt (ls, vls, t) =
  let tvs = Term.t_ty_freevars Ty.Stv.empty t in
  let tvs = List.fold_left (fun acc vs -> Ty.ty_freevars acc vs.vs_ty) tvs vls in
  fprintf fmt ";; %S@\n" ls.ls_name.id_string;
  fprintf fmt
    "@[<hv2>(assert@ @[<hv2>%a@])@]@\n@\n"
    (print_par info (fun fmt -> fprintf fmt
      "(forall @[(%a)@]@ @[<hv2>(= @[<h>(%a %a)@]@ %a)@])"
         (print_typed_var_list info) vls
         (print_ident info) ls.ls_name
         (print_var_list info) vls
         (print_expr info) t
     )) tvs




(* TODO if the property doesnt begin with quantifier, then we print it first.
   Else, we print it afterwards. *)
let print_incremental_axiom info fmt =
  List.iter (print_prop info fmt) info.incr_list_axioms;
  List.iter (print_ldecl_axiom info fmt) info.incr_list_ldecls;
  add_check_sat info fmt

let print_prop_decl vc_loc vc_attrs env printing_info info fmt k pr f = match k with
  | Paxiom ->
      if info.info_incremental && has_quantification f then
        info.incr_list_axioms <- (pr, f) :: info.incr_list_axioms
      else
        print_prop info fmt (pr, f)
  | Pgoal ->
      let tvs = Term.t_ty_freevars Ty.Stv.empty f in
      if not (Ty.Stv.is_empty tvs) then unsupported "smt: monomorphise goal must be applied";
      fprintf fmt ";; Goal %S@\n" pr.pr_name.id_string;
      (match pr.pr_name.id_loc with
        | None -> ()
        | Some loc -> fprintf fmt ";; File %a@\n" Loc.pp_position loc);
      info.info_in_goal <- true;
      fprintf fmt "@[(assert@\n";
      fprintf fmt "  @[(not@ %a))@]@\n@\n" (print_fmla info) f;
      info.info_in_goal <- false;
      add_check_sat info fmt;

      (* If in incremental mode, we empty the list of axioms we stored *)
      if info.info_incremental then
        print_incremental_axiom info fmt;

      let model_list = print_info_model info in

      let type_sorts =
        Mstr.map_filter
          (fun ts -> Mts.find_opt ts info.ty_tysymbol)
          info.type_sorts
      in

      printing_info := Some {
        why3_env = env;
        vc_term_loc = vc_loc;
        vc_term_attrs = vc_attrs;
        queried_terms = model_list;
        type_coercions = info.type_coercions;
        type_fields = info.type_fields;
        type_sorts = type_sorts;
        record_fields = info.record_fields;
        constructors = info.constructors;
        set_str = info.info_labels;
      }
  | Plemma -> assert false

let print_constructor_decl info is_record fmt (ls,args) =
  let cons_name = sprintf "%a" (print_ident info) ls.ls_name in
  info.constructors <- Mstr.add cons_name ls info.constructors;
  let field_names =
    (match args with
    | [] -> fprintf fmt "(%a)" (print_ident info) ls.ls_name; []
    | _ ->
        fprintf fmt "@[(%a@ " (print_ident info) ls.ls_name;
        let field_names, _ =
          List.fold_left2
          (fun (acc, i) ty pr ->
            let field_name =
              match pr with
              | Some pr ->
                  if not is_record then
                    unsupported "smtv2: sum types should not have projections";
                  let field_name = sprintf "%a" (print_ident info) pr.ls_name in
                  fprintf fmt "(%s" field_name;
                  let field_trace =
                    try
                      let attr = Sattr.choose (Sattr.filter (fun l ->
                        Strings.has_prefix ~prefix:"model_trace:" l.attr_string)
                        pr.ls_name.id_attrs) in
                      Strings.remove_prefix ~prefix:"model_trace:" attr.attr_string
                    with
                      Not_found -> ""
                  in
                  {field_name; field_trace; field_ident= Some pr.ls_name}
              | None ->
                  let field_name = id_fresh (ls.ls_name.id_string^"_proj") in
                  let field_name = create_vsymbol field_name ty(*dummy*) in
                  let field_name = sprintf "%a" (print_var info) field_name in
                  fprintf fmt "(%s" field_name;
                  {field_name; field_trace= ""; field_ident= None}
            in
            fprintf fmt " %a)" (print_type info) ty;
            (field_name :: acc, succ i)) ([], 1) ls.ls_args args
        in
        fprintf fmt ")@]";
        List.rev field_names)
  in

  info.constr_proj_id <-
    Mls.add ls (List.map (fun x -> x.field_name) field_names) info.constr_proj_id;
  if Strings.has_suffix ~suffix:"'mk" ls.ls_name.id_string then
    begin try
      let args = List.map Option.get args in
      info.record_fields <- Mls.add ls args info.record_fields
    with _ -> ()
    end

let print_data_decl info fmt (ts,cl) =
  let is_record = match cl with [_] -> true | _ -> false in
  let sort_name = sprintf "%a" (print_ident info) ts.ts_name in
  info.type_sorts <- Mstr.add sort_name ts info.type_sorts;
  fprintf fmt "@[(%a@ %a)@]"
    (print_ident info) ts.ts_name
    (print_list space (print_constructor_decl info is_record)) cl

let print_data_def info fmt (ts,cl) =
  let is_record = match cl with [_] -> true | _ -> false in
  if ts.ts_args <> [] then
    let args = List.map (fun arg -> arg.tv_name) ts.ts_args in
    fprintf fmt "@[(par (%a) (%a))@]"
      (print_list space (print_ident info)) args
      (print_list space (print_constructor_decl info is_record)) cl
  else
    fprintf fmt "@[(%a)@]"
      (print_list space (print_constructor_decl info is_record)) cl

let print_sort_decl info fmt (ts,_) =
  let sort_name = sprintf "%a" (print_ident info) ts.ts_name in
  info.type_sorts <- Mstr.add sort_name ts info.type_sorts;
  fprintf fmt "@[(%a %d)@]"
    (print_ident info) ts.ts_name
    (List.length ts.ts_args)

let set_produce_models fmt info =
  if info.info_cntexample then
    fprintf fmt "(set-option :produce-models true)@\n"

let set_incremental fmt info =
  if info.info_set_incremental then
    fprintf fmt "(set-option :incremental true)@\n"

let meta_counterexmp_need_push =
  Theory.register_meta_excl "counterexample_need_smtlib_push" []
                            ~desc:"Internal@ use@ only"

let meta_incremental =
  Theory.register_meta_excl "meta_incremental" []
                            ~desc:"Internal@ use@ only"

let meta_supports_minimize =
  Theory.register_meta_excl "supports_smtlib_minimize" []
                            ~desc:"solver supports SMTLIB `(minimize term)`"

let smtlib_minimize_attr = Ident.create_attribute "smtlib:minimize"

let meta_supports_reason_unknown =
  Theory.register_meta_excl "supports_smt_get_info_unknown_reason" []
                            ~desc:"Internal@ use@ only"


let print_decl vc_loc vc_attrs env printing_info info fmt d =
  match d.d_node with
  | Dtype ts ->
      print_type_decl info fmt ts
  | Ddata [(ts,_)] when query_syntax info.info_syn ts.ts_name <> None ->
      let st = Option.get (query_syntax info.info_syn ts.ts_name) in
      info.type_sorts <- Mstr.add st ts info.type_sorts
  | Ddata dl ->
      begin match info.info_version with
      | V20 ->
          fprintf fmt "@[<v2>(declare-datatypes ()@ (%a))@]@\n@\n"
            (print_list space (print_data_decl info)) dl
      | V26 | V26Par ->
          fprintf fmt "@[<v2>(declare-datatypes (%a)@ (%a))@]@\n@\n"
            (print_list space (print_sort_decl info)) dl
            (print_list space (print_data_def info)) dl
      end
  | Dparam ls ->
      collect_model_ls info ls;
      print_param_decl info fmt ls
  | Dlogic dl -> begin
      match info.info_version with
      | V20 | V26 ->
          print_list nothing (print_logic_decl info) fmt dl
      | V26Par -> begin
          match dl with
          | ([(s,_) as dl])
            when not (Sid.mem s.ls_name (get_used_syms_decl d)) ->
              print_logic_decl info fmt dl
          | dl ->
              print_rec_logic_decl info fmt dl
        end
    end
  | Dind _ -> unsupportedDecl d
                "smtv2: inductive definitions are not supported"
  | Dprop(Paxiom,_,({t_node = Tapp(_ps,[t]); t_attrs = a }))
    when Sattr.mem smtlib_minimize_attr a ->
      if info.info_supports_minimize then
        fprintf fmt "@[<v2>(minimize %a)@]@\n@\n" (print_term info) t
  | Dprop (k,pr,f) ->
      if Mid.mem pr.pr_name info.info_syn then () else
      print_prop_decl vc_loc vc_attrs env printing_info info fmt k pr f


let print_task version args ?old:_ fmt task =
  let cntexample = Driver.get_counterexmp task in
  let incremental =
    let incr_meta = Task.find_meta_tds task meta_incremental in
    not (Task.HStdecl.is_empty incr_meta)
  in
  let incremental = Debug.test_flag debug_incremental || incremental in
  let need_push =
    let need_push_meta = Task.find_meta_tds task meta_counterexmp_need_push in
    not (Task.HStdecl.is_empty need_push_meta)
  in
  let supports_reason_unknown =
    let m = Task.find_meta_tds task meta_supports_reason_unknown in
    not (Task.HStdecl.is_empty m)
  in
  let supports_minimize =
    let m = Task.find_meta_tds task meta_supports_minimize in
    not (Task.HStdecl.is_empty m)
  in
  let g,_ = Task.task_separate_goal task in
  let vc_loc =
    Theory.(match g.td_node with
        | Decl { d_node = Dprop (_,_,t) } -> t.t_loc
        | _ -> None)
  in
  let vc_attrs = (Task.task_goal_fmla task).t_attrs in
  let vc_info = {vc_inside = false; vc_loc; vc_func_name = None} in
  let info = {
    info_syn = Discriminate.get_syntax_map task;
    info_rliteral = Printer.get_rliteral_map task;
    info_model = S.empty;
    info_in_goal = false;
    info_vc_term = vc_info;
    info_printer = ident_printer ();
    type_coercions = Mty.empty;
    type_fields = Mty.empty;
    type_sorts = Mstr.empty;
    ty_tysymbol = Mts.empty;
    info_version = version;
    meta_model_projection = Task.on_tagged_ls Theory.meta_model_projection task;
    meta_record_def = Task.on_tagged_ls Theory.meta_record task;
    record_fields = Mls.empty;
    constr_proj_id = Mls.empty;
    constructors = Mstr.empty;
    info_cntexample_need_push = need_push;
    info_cntexample = cntexample;
    info_incremental = incremental;
    info_labels = Mstr.empty;
    (* info_set_incremental add the incremental option to the header. It is not
       needed for some provers
    *)
    info_set_incremental = not need_push && incremental;
    info_supports_reason_unknown = supports_reason_unknown;
    info_supports_minimize = supports_minimize;
    incr_list_axioms = [];
    incr_list_ldecls = [];
    }
  in
  print_prelude fmt args.prelude;
  set_produce_models fmt info;
  set_incremental fmt info;
  print_th_prelude task fmt args.th_prelude;
  let rec print_decls = function
    | Some t ->
        print_decls t.Task.task_prev;
        begin match t.Task.task_decl.Theory.td_node with
        | Theory.Decl d ->
            begin try print_decl vc_loc vc_attrs args.env args.printing_info info fmt d
            with Unsupported s -> raise (UnsupportedDecl (d,s)) end
        | _ -> () end
    | None -> () in
  print_decls task;
  pp_print_flush fmt ()

let () = register_printer "smtv2" (print_task V20)
  ~desc:"Printer@ for@ the@ SMTlib@ version@ 2@ format."
let () = register_printer "smtv2.6" (print_task V26)
  ~desc:"Printer@ for@ the@ SMTlib@ version@ 2.6@ format."
let () = register_printer "smtv2.6par" (print_task V26Par)
  ~desc:"Printer@ for@ the@ SMTlib@ version@ 2.6@ format with (par construct from version 3."

open Why3
open Why3.Json_base

type prover_stat =
  {
    mutable count     : int;
    mutable max_time  : float;
    mutable max_steps : int;
  }

type stats = prover_stat Whyconf.Hprover.t

type result_info =
  | Proved of stats * int
  | Not_Proved of
       Gnat_expl.extra_info *
       (Model_parser.model * Check_ce.rac_result option) list *
       (string * string) option *
        Gnat_expl.unproved_status

type msg =
  { result           : bool;
    stats            : stats option;
    stats_checker    : int;
    check_tree       : Json_base.json;
    extra_info       : Gnat_expl.extra_info;
    cntexmp_models   : (Model_parser.model * Check_ce.rac_result option) list;
    manual_proof     : (string * string) option;
    unproved_status : Gnat_expl.unproved_status
  }

let msg_set : msg Gnat_expl.HCheck.t = Gnat_expl.HCheck.create 17

let warning_list : string list ref = ref []

let add_warning ?loc s =
  let s =
    match loc with
    | Some loc ->
        let file, line1, col1, line2, col2 = Loc.get loc in
        Format.sprintf "%s:(%d:%d)-(%d:%d): %s" file line1 col1 line2 col2 s
    | None -> s
  in
  warning_list := s :: !warning_list

let () = Loc.set_warning_hook add_warning

let adapt_stats statsopt =
  match statsopt with
  | None -> None
  | Some stats ->
      let newstats = Whyconf.Hprover.create 3 in
      Whyconf.Hprover.iter (fun k v ->
        let name = k.Whyconf.prover_name in
        Whyconf.Hprover.add newstats k {v with max_steps =
          Gnat_config.back_convert_steps ~prover:name v.max_steps}) stats;
      Some newstats

let register check check_tree result =
  let valid, extra_info, stats, models, manual, unproved_status =
    match result with
    | Proved (stats, stats_checker) ->
        true,
        {Gnat_expl.pretty_node = None; inlined = None},
        Some (stats, stats_checker),
        [],
        None,
        Gnat_expl.Unknown
    | Not_Proved (extra_info, models, manual, unproved_status) ->
        false, extra_info, None, models, manual, unproved_status
  in
  if (Gnat_expl.HCheck.mem msg_set check) then assert false
  else begin
    let stats_g = Option.map (fun x -> let (stats, _) = x in stats) stats in
    let stats_checker = Option.map (fun x -> let (_, sc) = x in sc) stats in
    let msg =
    { result         = valid;
      extra_info     = extra_info;
      stats          = adapt_stats stats_g;
      stats_checker  = Option.value ~default:0 stats_checker;
      check_tree     = check_tree;
      cntexmp_models = models;
      manual_proof   = manual;
      unproved_status = unproved_status } in
    Gnat_expl.HCheck.add msg_set check msg
  end

let get_cntexmp_models =
  List.map (function
  (m, r) ->
      let json_result_state (state, _log) =
        let more = match state with
          | Check_ce.Res_fail (ctx, t) ->
              let t =
                Ident.Sattr.fold Term.t_attr_add ctx.Pinterp_core.attrs t in
              let check = match Gnat_expl.search_labels t with
                | Some Gnat_expl.{check={id; check_kind; sloc}} ->
                    let file, line, col =
                      Gnat_loc.explode (Gnat_loc.orig_loc sloc) in
                    Record [
                      "id", Int id;
                      "vc_kind", String (Gnat_expl.check_kind_to_ada check_kind);
                      "sloc", Record [
                        "file", String file;
                        "line", Int line;
                        "col", Int col;
                      ]
                    ]
                | None -> Null in
              ["check", check]
          | Check_ce.Res_stuck reason | Check_ce.Res_incomplete reason ->
              ["reason", String reason]
          | _ -> [] in
        let state =
          ["state", String (Check_ce.string_of_rac_result_state state)] in
        Record (state @ more) in
      let rcd_only_cntexmp_model = [ "cntexmp", (Model_parser.json_model m) ] in
      match r with
      | None -> Record rcd_only_cntexmp_model
      | Some (Check_ce.RAC_not_done _) -> Record rcd_only_cntexmp_model
      | Some (Check_ce.RAC_done (state, _log)) ->
          Record (List.append
            rcd_only_cntexmp_model
            [ "giant_step_rac_result", (json_result_state (state, _log)) ])
    )

let get_manual_proof_info info =
  match info with
  | None -> []
  | Some (fname, cmd) ->
      [ "vc_file", String (Sys.getcwd () ^ Filename.dir_sep ^ fname);
        "editor_cmd", String cmd
      ]

let get_prover_stats stat =
  Record [
    "count", Int stat.count;
    "max_steps", Int stat.max_steps;
    "max_time", StandardFloat stat.max_time
  ]

let get_stats (stats, stat_checker) =
  (* Compute the stats for goal solved by transformations as a fake prover. *)
  let fake_prover_ch =
    Whyconf.{prover_name = "Checker"; prover_version = ""; prover_altern = ""}
  in
  match stats with
  | None -> []
  | Some s ->
    if stat_checker <> 0 then
      Whyconf.Hprover.add s fake_prover_ch
        {count = stat_checker; max_steps = 0; max_time = 0.0};
    let kv_list = Whyconf.Hprover.fold (fun k v acc -> (k,v)::acc) s [] in
    let get_name pr = pr.Whyconf.prover_name in
    [ "stats",
      Record (List.map (fun (k,v) -> get_name k, get_prover_stats v) kv_list) ]

let opt_int i = Option.value ~default:0 i

let get_extra_info i =
  match i with
  | { Gnat_expl.pretty_node = i; inlined = inline } ->
      Record [
        "node", Int (opt_int i);
        "inline", Int (opt_int inline)
      ]

let get_unproved_status status =
  let status, time, steps, memory =
    match status with
    | Gnat_expl.Unknown ->
        "unknown", false, false, false
    | Gnat_expl.Gave_up ->
        "gave_up", false, false, false
    | Gnat_expl.Limit { timeout; step; memory } ->
        "limit", timeout, step, memory
  in
  Record [
    "status", String status;
    "time", Bool time;
    "steps", Bool steps;
    "memory", Bool memory
  ]

let get_msg (check, m) =
  Record (
    List.concat [
      [ "id", Int check.Gnat_expl.id ;
        "check_kind", String (Gnat_expl.check_kind_to_ada check.Gnat_expl.check_kind) ;
        "result", Bool m.result ;
        "check_tree", m.check_tree ;
        "extra_info", get_extra_info m.extra_info ;
        "unproved_status", get_unproved_status m.unproved_status
      ] ;
      get_stats (m.stats, m.stats_checker);
      ["cntexmps", List (get_cntexmp_models m.cntexmp_models)];
      get_manual_proof_info m.manual_proof
    ]
  )

(* In case several models are returned by Why3, we sort them by id. *)
let sort_messages (l : (Gnat_expl.check * msg) list) =
  List.sort (fun x y -> compare (fst x).Gnat_expl.id (fst y).Gnat_expl.id) l

let get_results () =
  let msg_set =
    Gnat_expl.HCheck.fold (fun k v acc -> (k,v) :: acc) msg_set []
  in
  "results", List (List.map get_msg (sort_messages msg_set))

let get_warnings () =
  match !warning_list with
  | [] -> []
  | l -> [("warnings", List (List.map (fun elem -> String elem) l))]

let get_timings () =
  let l = Hashtbl.fold (fun k v acc -> (k,v)::acc) (Debug.Stats.get_timings ()) [] in
  let get_name s = s in
  "timings", Record (List.map (fun (k,(v,_n)) -> get_name k, StandardFloat v) l)

let get_entity () =
  "entity", Int Gnat_config.entity

(* The main function, where we build the final Record to be printed using
Why3.Json_base.print_json function. *)
let print_messages () =
  print_json_single_line Format.std_formatter (
    Record (
      List.concat [
        [get_results (); get_timings (); get_entity ()];
        get_warnings ()
      ]
    )
  )

exception KnownMeta of meta
exception UnknownMeta of string
exception BadMetaArity of meta * int
exception MetaTypeMismatch of meta * meta_arg_type * meta_arg_type
exception IllFormedMeta of meta * string

let meta_table = Hstr.create 17

let mk_meta =
  let c = ref (-1) in
  fun desc s al excl -> {
    meta_name = s;
    meta_type = al;
    meta_excl = excl;
    meta_desc = desc;
    meta_tag  = (incr c; !c);
  }

let register_meta ~desc s al excl =
  try
    let m = Hstr.find meta_table s in
    if al = m.meta_type && excl = m.meta_excl then m
    else raise (KnownMeta m)
  with Not_found ->
    let m = mk_meta desc s al excl in
    Hstr.add meta_table s m;
    m

let register_meta_excl ~desc s al = register_meta ~desc s al true
let register_meta      ~desc s al = register_meta ~desc s al false

let lookup_meta s = Hstr.find_exn meta_table (UnknownMeta s) s

let empty_module env n p = {
  muc_theory = create_theory ~path:p n;
  muc_units  = [];
  muc_import = [empty_ns];
  muc_export = [empty_ns];
  muc_known  = Mid.empty;
  muc_local  = Sid.empty;
  muc_used   = Sid.empty;
  muc_env    = env;
}

let close_module, restore_module =
  let h = Wid.create 17 in
  (fun uc ->
     let th = close_theory uc.muc_theory in (* catches errors *)
     let m = { mod_theory = th;
               mod_units  = List.rev uc.muc_units;
               mod_export = List.hd uc.muc_export;
               mod_known  = uc.muc_known;
               mod_local  = uc.muc_local;
               mod_used   = uc.muc_used; } in
     Wid.set h th.th_name m;
     m),
  (fun th -> Wid.find h th.th_name)

let open_scope uc s = match uc.muc_import with
  | ns :: _ -> { uc with
      muc_theory = Theory.open_scope uc.muc_theory s;
      muc_units  = [Uscope (s, uc.muc_units)];
      muc_import =       ns :: uc.muc_import;
      muc_export = empty_ns :: uc.muc_export; }
  | [] -> assert false

let close_scope uc ~import =
  let th = Theory.close_scope uc.muc_theory ~import in
  match List.rev uc.muc_units, uc.muc_import, uc.muc_export with
  | [Uscope (_,ul1)], _ :: sti, _ :: ste -> (* empty scope *)
      { uc with muc_theory = th;  muc_units  = ul1;
                muc_import = sti; muc_export = ste; }
  | Uscope (s,ul1) :: ul0, _ :: i1 :: sti, e0 :: e1 :: ste ->
      let i1 = if import then merge_ns false e0 i1 else i1 in
      let i1 = add_ns false s e0 i1 in
      let e1 = add_ns true  s e0 e1 in
      { uc with
          muc_theory = th;
          muc_units  = Uscope (s,ul0) :: ul1;
          muc_import = i1 :: sti;
          muc_export = e1 :: ste; }
  | _ -> assert false

let import_scope uc ql = match uc.muc_import with
  | i1 :: sti ->
      let th = Theory.import_scope uc.muc_theory ql in
      let i1 = merge_ns false (ns_find_ns i1 ql) i1 in
      { uc with muc_theory = th; muc_import = i1::sti }
  | _ -> assert false

let use_export uc ({mod_theory = mth} as m) =
  let th = Theory.use_export uc.muc_theory mth in
  let uc = if Sid.mem mth.th_name uc.muc_used then uc
    else { uc with
      muc_known = merge_known uc.muc_known m.mod_known;
      muc_used  = Sid.add mth.th_name uc.muc_used } in
  match uc.muc_import, uc.muc_export with
  | i0 :: sti, e0 :: ste -> { uc with
      muc_theory = th;
      muc_units  = Uuse m :: uc.muc_units;
      muc_import = merge_ns false m.mod_export i0 :: sti;
      muc_export = merge_ns true  m.mod_export e0 :: ste; }
  | _ -> assert false

let store_path, store_module, restore_path, restore_module_id =
  let id_to_path = Wid.create 17 in
  let id_to_pmod = Wid.create 17 in
  let store_path {muc_theory = uc} path id =
    (* this symbol already belongs to some theory *)
    if Wid.mem id_to_path id then () else
    let prefix = List.rev (id.id_string :: path @ uc.uc_prefix) in
    Wid.set id_to_path id (uc.uc_path, uc.uc_name.id_string, prefix) in
  let store_module pmod  =
    let th = pmod.mod_theory in
    let id = th.th_name in
    (* this symbol is already a module *)
    if Wid.mem id_to_path id then () else begin
        Wid.set id_to_path id (th.th_path, id.id_string, []);
        Sid.iter (fun id -> Wid.set id_to_pmod id pmod) pmod.mod_local;
        Wid.set id_to_pmod id pmod;
      end
  in
  let restore_path id = Wid.find id_to_path id in
  let restore_module_id id = Wid.find id_to_pmod id in
  store_path, store_module, restore_path, restore_module_id

      (* FIXME add correspondance for "let lemma" to cl.pr_table *)
      let dl = mk_vc uc (create_let_decl ld) in
      List.fold_left (add_pdecl_raw ~warn:false) uc dl
  | PDlet ld ->
      begin match ld with
        | LDvar ({pv_vs=vs}, _) when Mvs.mem vs inst.mi_pv ->
            raise (CannotInstantiate vs.vs_name)
        | LDrec rdl ->
            let no_inst {rec_sym = rs} =
              if Mrs.mem rs inst.mi_rs then
                raise (CannotInstantiate rs.rs_name) in
            List.iter no_inst rdl
        | _ -> () end;
      let reads = match ld with
        | LDvar (_,e) -> e.e_effect.eff_reads
        | LDsym (_,c) -> cty_reads c.c_cty
        | LDrec rdl -> List.fold_left (fun spv {rec_rsym = s} ->
            Spv.union spv (cty_reads s.rs_cty)) Spv.empty rdl in
      freeze_foreign cl reads;
      let sm, ld = clone_let_defn loc cl (sm_of_cl cl) ld in
      cl.pv_table <- sm.sm_pv; cl.rs_table <- sm.sm_rs;
      add_pdecl ~warn:false ~vc:false uc (create_let_decl ld)
  | PDexn ({xs_name = id} as xs) when Mxs.mem xs inst.mi_xs ->
      let xs' = Mxs.find xs inst.mi_xs in
      begin try let ity = clone_ity cl xs.xs_ity in
                ignore (ity_match isb_empty xs'.xs_ity ity)
        with TypeMismatch _ -> raise (BadInstance (BadI_xs_type id)) end;
      if mask_spill xs'.xs_mask xs.xs_mask then
        raise (BadInstance (BadI_xs_mask id));
      cl.xs_table <- Mxs.add xs xs' cl.xs_table;
      uc
  | PDexn xs ->
      let id = id_clone xs.xs_name in
      let ity = clone_ity cl xs.xs_ity in
      let xs' = create_xsymbol id ~mask:xs.xs_mask ity in
      cl.xs_table <- Mxs.add xs xs' cl.xs_table;
      add_pdecl ~warn:false ~vc:false uc (create_exn_decl xs')
  | PDpure ->
      let uc = List.fold_left (clone_decl inst cl) uc d.pd_pure in
      assert (d.pd_meta = []); (* pure decls do not produce metas *)
      uc

let impl_cl = empty_clones' Sid.empty

let mod_table = Wid.create 17

let theory_add_clone = Theory.add_clone_internal ()

let add_clone uc mi =
  let sm = {
    sm_ty = Mts.map ty_of_ity mi.mi_ty;
    sm_ts = Mts.map (fun s -> s.its_ts) mi.mi_ts;
    sm_ls = mi.mi_ls;
    sm_pr = mi.mi_pr } in
  let uc = add_use uc (Sid.empty |>
    Mts.fold (fun _ ts s -> syms_of_ts s ts) sm.sm_ts |>
    Mts.fold (fun _ ty s -> syms_of_ty s ty) sm.sm_ty |>
    Mls.fold (fun _ ls s -> syms_of_ls s ls) sm.sm_ls) in
  { uc with
      muc_theory = theory_add_clone uc.muc_theory mi.mi_mod.mod_theory sm;
      muc_units  = Uclone mi :: uc.muc_units }

let decl_impl uc d =
  match d.d_node with
  | Dprop (Pgoal, pr, f) ->
     (* when the prop is a Pgoal clone_pdecl do not copy it *)
     let attr = Sattr.remove Ident.useraxiom_attr pr.pr_name.id_attrs in
     let pr' = create_prsymbol (id_attr pr.pr_name attr) in
     impl_cl.pr_table <- Mpr.add pr pr' impl_cl.pr_table;
     let d = create_prop_decl Pgoal pr' (clone_fmla impl_cl f) in
     add_pdecl ~warn:false ~vc:false uc (create_pure_decl d)
  | _ -> uc

let need_copy m =
  Sid.exists (fun id -> Wid.mem mod_table id) m.mod_theory.th_used

let pdecl_impl inst uc d =
  let uc = clone_pdecl None inst impl_cl uc d in
  match d.pd_node with
  | PDpure ->
     List.fold_left decl_impl uc d.pd_pure
  | _ -> uc

let rec mi_impl e mi =
  let aux fold add empty findk findv m =
    fold (fun k v m -> add (findk impl_cl k) (findv impl_cl v) m) m empty in
  let mi_mod = mod_impl e mi.mi_mod in
  {
    mi_mod = mi_mod;
    mi_ty = aux Mts.fold Mts.add Mts.empty cl_find_ts clone_ity mi.mi_ty;
    mi_ts = aux Mts.fold Mts.add Mts.empty cl_find_ts cl_find_its mi.mi_ts;
    mi_ls = aux Mls.fold Mls.add Mls.empty cl_find_ls cl_find_ls mi.mi_ls;
    mi_pr = aux Mpr.fold Mpr.add Mpr.empty cl_find_pr cl_find_pr mi.mi_pr;
    mi_pk = aux Mpr.fold Mpr.add Mpr.empty cl_find_pr (fun _ k -> k) mi.mi_pk;
    mi_pv = Mvs.(aux fold add empty (fun cl vs -> (find vs cl.pv_table).pv_vs)
                   cl_find_pv mi.mi_pv);
    mi_rs = aux Mrs.fold Mrs.add Mrs.empty cl_find_rs cl_find_rs mi.mi_rs;
    mi_xs = aux Mxs.fold Mxs.add Mxs.empty cl_find_xs cl_find_xs mi.mi_xs;
    mi_df = mi.mi_df;
  }

and unit_impl e inst uc = function
  | Udecl d -> pdecl_impl inst uc d
  | Uuse m -> use_export uc (mod_impl e m)

  | Umeta (m, al) ->
     begin try add_meta uc m (List.map (function
       | MAty ty -> MAty (clone_ty impl_cl ty)
       | MAts ts -> MAts (cl_find_ts impl_cl ts)
       | MAls ls -> MAls (cl_find_ls impl_cl ls)
       | MApr pr -> MApr (cl_find_pr impl_cl pr)
       | a -> a) al)
     with Not_found -> uc end

  | Uscope (n, ul) ->
     let uc = open_scope uc n in
     let uc = List.fold_left (unit_impl e inst) uc ul in
     close_scope ~import:false uc

  | Uclone mi ->
     try add_clone uc (mi_impl e mi) with
     | Not_found -> uc

and mod_impl'' e m =
  impl_cl.cl_local <- Sid.union impl_cl.cl_local m.mod_local;
  let id = id_clone m.mod_theory.th_name in
  let muc = empty_module e id m.mod_theory.th_path in
  let muc = List.fold_left (unit_impl e (empty_mod_inst m)) muc m.mod_units in
  muc

and mod_impl' e m =
  close_module (mod_impl'' e m)

and mod_impl e m =
  let id = m.mod_theory.th_name in
  try Wid.find mod_table id with
  | Not_found ->
     if not (need_copy m)
     then m
     else begin
         let m = mod_impl' e m in
         Wid.set mod_table id m;
         m
       end

let clone_export' ?loc uc m inst cl =
  let rec add_unit uc u = match u with
    | Udecl d -> clone_pdecl loc inst cl uc d
    | Uuse m -> use_export uc m
    | Uclone mi ->
        begin try add_clone uc { mi_mod = mi.mi_mod;
          mi_ty = Mts.map (clone_ity cl) mi.mi_ty;
          mi_ts = Mts.map (cl_find_its cl) mi.mi_ts;
          mi_ls = Mls.map (cl_find_ls cl) mi.mi_ls;
          mi_pr = Mpr.map (cl_find_pr cl) mi.mi_pr;
          mi_pk = mi.mi_pk;
          mi_pv = Mvs.map (cl_find_pv cl) mi.mi_pv;
          mi_rs = Mrs.map (cl_find_rs cl) mi.mi_rs;
          mi_xs = Mxs.map (cl_find_xs cl) mi.mi_xs;
          mi_df = mi.mi_df}
        with Not_found -> uc end
    | Umeta (m,al) ->
        begin try add_meta uc m (List.map (function
          | MAty ty -> MAty (clone_ty cl ty)
          | MAts ts -> MAts (cl_find_ts cl ts)
          | MAls ls -> MAls (cl_find_ls cl ls)
          | MApr pr -> MApr (cl_find_pr cl pr)
          | a -> a) al)
        with Not_found -> uc end
    | Uscope (n,ul) ->
        let uc = open_scope uc n in
        let uc = List.fold_left add_unit uc ul in
        close_scope ~import:false uc in
  let uc = List.fold_left add_unit uc m.mod_units in
  let local id _ = Sid.mem id m.mod_local in
  let mi = {
    mi_mod = m;
    mi_ty  = Mts.filter (fun k -> local k.ts_name) cl.ty_table;
    mi_ts  = Mts.filter (fun k -> local k.ts_name) cl.ts_table;
    mi_ls  = Mls.filter (fun k -> local k.ls_name) cl.ls_table;
    mi_pr  = Mpr.filter (fun k -> local k.pr_name) cl.pr_table;
    mi_pk  = inst.mi_pk;
    mi_pv  = Mvs.filter (fun k -> local k.vs_name) cl.pv_table;
    mi_rs  = Mrs.filter (fun k -> local k.rs_name) cl.rs_table;
    mi_xs  = Mxs.filter (fun k -> local k.xs_name) cl.xs_table;
    mi_df  = inst.mi_df} in
  add_clone uc mi

let clone_export ?loc uc m inst =
  clone_export' ?loc uc m inst (cl_init m inst)

let mod_impl_register e m mimpl inst =
  let mimpl' = mod_impl'' e mimpl in
  let mimpl' = open_scope mimpl' "some'scope" in
  let inst = {
      mi_mod = inst.mi_mod;
      mi_ty = Mts.map (clone_ity impl_cl) inst.mi_ty;
      mi_ts = Mts.map (cl_find_its impl_cl) inst.mi_ts;
      mi_ls = Mls.map (cl_find_ls impl_cl) inst.mi_ls;
      mi_pr = Mpr.map (cl_find_pr impl_cl) inst.mi_pr;
      mi_pk = inst.mi_pk;
      mi_pv = Mvs.map (cl_find_pv impl_cl) inst.mi_pv;
      mi_rs = Mrs.map (cl_find_rs impl_cl) inst.mi_rs;
      mi_xs = Mxs.map (cl_find_xs impl_cl) inst.mi_xs;
      mi_df = inst.mi_df
    } in
  impl_cl.cl_local <- Sid.union impl_cl.cl_local m.mod_local;
  let mimpl' = clone_export' mimpl' m inst impl_cl in
  let mimpl' = close_scope mimpl' ~import:false in
  let mimpl' = close_module mimpl' in
  Wid.set mod_table mimpl.mod_theory.th_name mimpl';
  Wid.set mod_table m.mod_theory.th_name mimpl'

(** {2 WhyML language} *)

type mlw_file = pmodule Mstr.t

let convert mm =
  let convert m = m.mod_theory in
  if Mstr.is_empty mm then Mstr.empty else
  match (snd (Mstr.choose mm)).mod_theory.th_path with
  | "why3" :: path ->
      begin try Env.base_language_builtin path
      with Not_found -> Mstr.map convert mm end
  | _ -> Mstr.map convert mm

let mlw_language = Env.register_language Env.base_language convert

module Hpath = Exthtbl.Make(struct
  type t = Env.pathname
  let hash = Hashtbl.hash
  let equal = (=)
end)

let mlw_language_builtin =
  let builtin s =
    if s = unit_module.mod_theory.th_name.id_string then unit_module else
    if s = ref_module.mod_theory.th_name.id_string then ref_module else
    if s = builtin_theory.th_name.id_string then builtin_module else
    if s = ignore_theory.th_name.id_string then ignore_module else
    if s = highord_theory.th_name.id_string then highord_module else
    if s = wf_module.mod_theory.th_name.id_string then wf_module else
    if s = bool_theory.th_name.id_string then bool_module else
    match tuple_theory_name s with
    | Some n -> tuple_module n
    | None -> raise Not_found in
  Hpath.memo 7 (function
    | [s] -> Mstr.singleton s (builtin s)
    | _   -> raise Not_found)

let () = Env.add_builtin mlw_language mlw_language_builtin

exception ModuleNotFound of Env.pathname * string

let read_module env path s =
  let path = if path = [] then ["why3"; s] else path in
  let mm = Env.read_library mlw_language env path in
  Mstr.find_exn (ModuleNotFound (path,s)) s mm

type its_defn = {
  itd_its          : itysymbol;
  itd_fields       : rsymbol list;
  itd_constructors : rsymbol list;
  itd_invariant    : term list;
  itd_witness      : expr option;
}

let mk_itd s f c i w = {
  itd_its = s;
  itd_fields = f;
  itd_constructors = c;
  itd_invariant = i;
  itd_witness = w;
}

let create_alias_decl id args ity =
  mk_itd (create_alias_itysymbol id args ity) [] [] [] None

let create_range_decl id ir =
  mk_itd (create_range_itysymbol id ir) [] [] [] None

let create_float_decl id fp =
  mk_itd (create_float_itysymbol id fp) [] [] [] None

let check_field stv f =
  let loc = f.pv_vs.vs_name.id_loc in
  let ftv = ity_freevars Stv.empty f.pv_ity in
  if not (Stv.subset ftv stv) then Loc.error ?loc
    (UnboundTypeVar (Stv.choose (Stv.diff ftv stv)));
  if not f.pv_ity.ity_pure then Loc.errorm ?loc
    "This field has non-pure type, it cannot be used \
     in a recursive type definition"

let its_recursive s =
  not s.its_nonfree && not s.its_private &&
  not s.its_mutable && not s.its_fragile &&
  s.its_mfields = [] && s.its_regions = [] &&
  s.its_reg_flg = [] && s.its_def = NoDef &&
  List.for_all (fun x -> x.its_frozen &&
    x.its_exposed && not x.its_liable &&
    x.its_fixed && x.its_visible) s.its_arg_flg

let create_semi_constructor id s fdl pjl invl =
  let tvl = List.map ity_var s.its_ts.ts_args in
  let rgl = List.map ity_reg s.its_regions in
  let ity = ity_app s tvl rgl in
  let res = create_vsymbol (result_id ()) (ty_of_ity ity) in
  let t = t_var res in
  let mk_q {pv_vs = v} p = t_equ (fs_app (ls_of_rs p) [t] v.vs_ty) (t_var v) in
  let q = create_post res (t_and_simp_l (List.map2 mk_q fdl pjl)) in
  let eff = match ity.ity_node with
    | Ityreg r -> eff_reset eff_empty (Sreg.singleton r)
    | _ -> eff_empty in
  let c = create_cty fdl invl [q] Mxs.empty Mpv.empty eff ity in
  create_rsymbol id c

let create_plain_record_decl ~priv ~mut id args fdl invl witn =
  let exn = Invalid_argument "Pdecl.create_plain_record_decl" in
  let attrs = Sattr.singleton builtin_attr in
  let cid = id_fresh ~attrs ?loc:id.pre_loc (id.pre_name ^ "'mk") in
  let add_fd fds (mut, fd) = Mpv.add_new exn fd mut fds in
  let fds = List.fold_left add_fd Mpv.empty fdl in
  let fdl = List.map snd fdl in
  let s = create_plain_record_itysymbol ~priv ~mut id args fds invl in
  let pjl = List.map (create_projection (invl = [] && not priv) s) fdl in
  let csl = if priv then [] else if invl <> [] then
    [create_semi_constructor cid s fdl pjl invl] else
    [create_constructor ~constr:1 cid s fdl] in
  if witn <> None then begin
    let ty = Ty.ty_tuple @@ List.map (fun fd -> fd.pv_vs.vs_ty) fdl in
    Option.iter (fun ({e_loc = loc} as e) ->
      if diverges e.e_effect.eff_oneway then Loc.errorm ?loc
        "This expression may not terminate, it cannot be a witness";
      if partial e.e_effect.eff_oneway then Loc.errorm ?loc
        "This expression may fail, it cannot be a witness";
      if not (Sxs.is_empty e.e_effect.eff_raises) then Loc.errorm ?loc
        "This expression may raise exceptions, it cannot be a witness";
      let ety = ty_of_ity e.e_ity in
      Loc.try2 ?loc ty_equal_check ety ty) witn
  end;
  mk_itd s pjl csl invl witn

let create_rec_record_decl s fdl =
  let exn = Invalid_argument "Pdecl.create_rec_record_decl" in
  if not (its_recursive s) then raise exn;
  let id = s.its_ts.ts_name in
  let attrs = Sattr.singleton builtin_attr in
  let cid = id_fresh ~attrs ?loc:id.id_loc (id.id_string ^ "'mk") in
  List.iter (check_field (Stv.of_list s.its_ts.ts_args)) fdl;
  let cs = create_constructor ~constr:1 cid s fdl in
  let pjl = List.map (create_projection true s) fdl in
  mk_itd s pjl [cs] [] None

let create_variant_decl exn get_its csl =
  (* named projections are the same in each constructor *)
  let fdl, rest = match csl with
    | (_,fdl)::csl -> fdl, csl | [] -> raise exn in
  let add_pj pjs (p, fd) = if p then Spv.add fd pjs else pjs in
  let get_pjs fdl = List.fold_left add_pj Spv.empty fdl in
  let pjs = get_pjs fdl in
  List.iter (fun (_, fdl) -> let s = get_pjs fdl in
    if not (Spv.equal s pjs) then raise exn) rest;
  (* therefore, we take them from the first constructor *)
  let add_pj (p, fd) pjl = if p then fd::pjl else pjl in
  let pjl = List.fold_right add_pj fdl [] in
  (* we must also check each field of each constructor *)
  let add_fd fds (_, fd) = Spv.add_new exn fd fds in
  let get_fds (_, fdl) = List.fold_left add_fd Spv.empty fdl in
  (* and now we can create the type symbol and the constructors *)
  let s = get_its (List.map get_fds csl) and constr = List.length csl in
  let mk_cs (id, fdl) = create_constructor ~constr id s (List.map snd fdl) in
  mk_itd s (List.map (create_projection true s) pjl) (List.map mk_cs csl) [] None

let create_plain_variant_decl id args csl =
  let exn = Invalid_argument "Pdecl.create_plain_variant_decl" in
  create_variant_decl exn (create_plain_variant_itysymbol id args) csl

let create_rec_variant_decl s csl =
  let exn = Invalid_argument "Pdecl.create_rec_variant_decl" in
  if not (its_recursive s) then raise exn;
  let stv = Stv.of_list s.its_ts.ts_args in
  let get_its fdl = List.iter (Spv.iter (check_field stv)) fdl; s in
  create_variant_decl exn get_its csl

module Hsity = Hashcons.Make (struct
  type t = ity

  let equal ity1 ity2 = match ity1.ity_node, ity2.ity_node with
    | Ityvar v1, Ityvar v2 -> tv_equal v1 v2
    | Ityreg r1, Ityreg r2 -> reg_equal r1 r2
    | Ityapp (s1,l1,r1), Ityapp (s2,l2,r2) ->
        its_equal s1 s2 &&
        List.for_all2 ity_equal l1 l2 &&
        List.for_all2 ity_equal r1 r2
    | _ -> false

  let hash ity = match ity.ity_node with
    | Ityvar v -> tv_hash v
    | Ityreg r -> reg_hash r
    | Ityapp (s,tl,rl) ->
        Hashcons.combine_list ity_hash
          (Hashcons.combine_list ity_hash (its_hash s) tl) rl

  let pure ity = match ity.ity_node with
    | Ityvar _ -> true
    | Ityreg _ -> false
    | Ityapp (_,tl,rl) ->
        let pure ity = ity.ity_pure in
        List.for_all pure tl && List.for_all pure rl

  let tag n ity = { ity with
    ity_pure = pure ity;
    ity_tag = Weakhtbl.create_tag n }
end)

let mk_ity node = {
  ity_node = node;
  ity_pure = true;
  ity_tag  = Weakhtbl.dummy_tag;
}

let mk_reg name s tl rl = {
  reg_name = id_register name;
  reg_its  = s;
  reg_args = tl;
  reg_regs = rl;
}

let ity_reg r              = Hsity.hashcons (mk_ity (Ityreg r))
let ity_var v              = Hsity.hashcons (mk_ity (Ityvar v))
let ity_app_unsafe s tl rl = Hsity.hashcons (mk_ity (Ityapp (s,tl,rl)))

let mk_its, restore_its =
  let ts_to_its = Wts.create 17 in
  (fun ~ts ~nfr ~priv ~mut ~frg ~mfld ~ofld ~regs ~aflg ~rflg ~def ->
    let its = {
      its_ts      = ts;
      its_nonfree = nfr;
      its_private = priv;
      its_mutable = mut;
      its_fragile = frg;
      its_mfields = mfld;
      its_ofields = ofld;
      its_regions = regs;
      its_arg_flg = aflg;
      its_reg_flg = rflg;
      its_def     = def;
    } in
    Wts.set ts_to_its ts its;
    its),
  (fun ts -> Wts.find ts_to_its ts)

let rec ity_of_ty ty = match ty.ty_node with
  | Tyvar v -> ity_var v
  | Tyapp (s,tl) ->
      let s = try restore_its s with Not_found ->
        invalid_arg "Ity.ity_of_ty" in
      ity_app s (List.map ity_of_ty tl) []

let rec ity_of_ty_pure ty = match ty.ty_node with
  | Tyvar v -> ity_var v
  | Tyapp (s,tl) ->
      let s = try restore_its s with Not_found ->
        invalid_arg "Ity.ity_of_ty_pure" in
      ity_app_pure s (List.map ity_of_ty_pure tl) []

let mk_flg ~frz ~exp ~lbl ~fxd ~vis = {
  its_frozen = frz; its_exposed = exp; its_liable = lbl;
  its_fixed  = fxd; its_visible = vis }

let its_of_ts ts priv ofld =
  assert (ts.ts_def = NoDef);
  let flg = mk_flg ~frz:priv ~exp:true ~lbl:priv ~fxd:true ~vis:true in
  mk_its ~ts ~nfr:priv ~priv ~mut:false ~frg:false ~mfld:[] ~ofld
    ~regs:[] ~aflg:(List.map (fun _ -> flg) ts.ts_args) ~rflg:[] ~def:NoDef

let create_rec_itysymbol id args =
  let ts = create_tysymbol id args NoDef in
  let flg = mk_flg ~frz:true ~exp:true ~lbl:false ~fxd:true ~vis:true in
  mk_its ~ts ~nfr:false ~priv:false ~mut:false ~frg:false ~mfld:[] ~ofld:[]
    ~regs:[] ~aflg:(List.map (fun _ -> flg) ts.ts_args) ~rflg:[] ~def:NoDef

let create_alias_itysymbol id args def =
  let ts = create_tysymbol id args (Alias (ty_of_ity def)) in
  let mut, ity = match def.ity_node with (* ignore the top region *)
    | Ityreg r -> true, ity_app_pure r.reg_its r.reg_args r.reg_regs
    | _ -> false, def in
  let regs = Sreg.elements (ity_top_regs Sreg.empty ity) in
  let flg = mk_flg ~frz:true ~exp:true ~lbl:false ~fxd:true ~vis:true in
  mk_its ~ts ~nfr:false ~priv:false ~mut ~frg:false ~mfld:[] ~ofld:[] ~regs
    ~aflg:(List.map (fun _ -> flg) args)
    ~rflg:(List.map (fun _ -> flg) regs) ~def:(Alias def)

let create_range_itysymbol id ir =
  let ts = create_tysymbol id [] (Range ir) in
  mk_its ~ts ~nfr:false ~priv:false ~mut:false ~frg:false ~mfld:[] ~ofld:[]
    ~regs:[] ~aflg:[] ~rflg:[] ~def:(Range ir)

let create_float_itysymbol id fp =
  let ts = create_tysymbol id [] (Float fp) in
  mk_its ~ts ~nfr:false ~priv:false ~mut:false ~frg:false ~mfld:[] ~ofld:[]
    ~regs:[] ~aflg:[] ~rflg:[] ~def:(Float fp)

let fields_of_invariant ftv flds invl =
  if invl = [] then Mpv.empty, flds else
  let fvs = Mpv.fold (fun v _ s -> Svs.add v.pv_vs s) flds Svs.empty in

  rs_name  : ident;
  rs_cty   : cty;
  rs_logic : rs_logic;
  rs_field : pvsymbol option;
}

and rs_logic =
  | RLnone            (* non-pure symbol *)
  | RLpv of pvsymbol  (* local let-function *)
  | RLls of lsymbol   (* top-level let-function or let-predicate *)
  | RLlemma           (* top-level or local let-lemma *)

module Rsym = MakeMSHW (struct
  type t = rsymbol
  let tag rs = rs.rs_name.id_tag
end)

module Srs = Rsym.S
module Mrs = Rsym.M
module Hrs = Rsym.H
module Wrs = Rsym.W

let rs_equal : rsymbol -> rsymbol -> bool = (==)
let rs_hash rs = id_hash rs.rs_name
let rs_compare rs1 rs2 = id_compare rs1.rs_name rs2.rs_name

let mk_rs, restore_rs =
  let ls_to_rs = Wls.create 17 in
  (fun id cty lg mf ->
    let rs = {
      rs_name  = id;
      rs_cty   = cty;
      rs_logic = lg;
      rs_field = mf;
    } in
    match lg with
    | RLls ls -> Wls.set ls_to_rs ls rs; rs
    | _ -> rs),
  (fun ls -> Wls.find ls_to_rs ls)

let create_user_prog_id {id_str = n; id_ats = attrs; id_loc = loc} =
  let get_attrs (attrs, loc) = function
    | ATstr attr -> Sattr.add attr attrs, loc | ATpos loc -> attrs, loc in
  let attrs, loc = List.fold_left get_attrs (Sattr.empty, loc) attrs in
  id_user ~attrs n loc

let create_user_id id =
  let id = create_user_prog_id id in
  if Sattr.mem Pmodule.ref_attr id.pre_attrs then Loc.errorm ?loc:id.pre_loc
    "reference markers are only admitted over program variables";
  id

  env              : Env.env;
  path             : Env.pathname;
  mutable file     : pmodule Mstr.t;
  mutable muc      : pmodule_uc option;
  mutable muc_intf : pmodule option
}

let state = (Stack.create () : slice Stack.t)

let open_file env path =
  assert (Stack.is_empty state || (Stack.top state).muc <> None);
  Stack.push {
      env = env;
      path = path;
      file = Mstr.empty;
      muc = None;
      muc_intf = None;
    } state

let close_file () =
  assert (not (Stack.is_empty state) && (Stack.top state).muc = None);
  (Stack.pop state).file

let discard_file () =
  assert (not (Stack.is_empty state));
  ignore (Stack.pop state)

let open_module ?intf ({id_str = nm; id_loc = loc} as id) =
  assert (not (Stack.is_empty state) && (Stack.top state).muc = None);
  let slice = Stack.top state in
  if Mstr.mem nm slice.file then Loc.errorm ~loc
    "module %s is already defined in this file" nm;
  let id = if intf = None
           then create_user_id id
           else id_user (nm ^ "'impl") loc in
  let muc = create_module slice.env ~path:slice.path id in
  slice.muc <- Some muc;
  slice.muc_intf <- None;
  if Debug.test_noflag debug_parse_only then begin
    match intf with
    | None -> ()
    | Some qid ->
       let mintf = Loc.try3 ~loc find_module slice.env slice.file qid in
       slice.muc_intf <- Some mintf
  end

exception Invalid_unit
exception Symbol_not_found of Ident.ident

let intf_mod_inst muc intf =

  let rec aux_units ns_muc ns_tuc inst ul =

    let add_type inst its =
      try
        let its' = ns_find_its ns_muc [its.ts_name.id_string] in
        { inst with mi_ts = Mts.add its its' inst.mi_ts }
      with Not_found -> raise (Symbol_not_found its.ts_name) in

    let add_logic inst ls =
      try
        let ls' = ns_find_ls ns_tuc [ls.ls_name.id_string] in

mlw_file:
| EOF
| mlw_module mlw_module_no_decl* EOF
    { Typing.close_file () }
| module_decl module_decl_no_head* EOF
    { let loc = floc $startpos($3) $endpos($3) in
      Typing.close_module loc; Typing.close_file () }

mlw_file_parsing_only:
| EOF { (Modules([])) }
| mlw_module_parsing_only mlw_module_no_decl_parsing_only* EOF { (Modules( [$1] @ $2)) }
| module_decl_parsing_only module_decl_no_head_parsing_only* EOF { (Decls( [$1] @ $2)) }


mlw_module:
| module_head module_decl_no_head* END
    { Typing.close_module (floc $startpos($3) $endpos($3)) }

mlw_module_parsing_only:
| module_head_parsing_only module_decl_no_head_parsing_only* END { ($1,$2) }

module_head:
| THEORY attrs(uident_nq)  { Typing.open_module $2 }
| MODULE attrs(uident_nq) intf = option(preceded(COLON, tqualid))
    { Typing.open_module ?intf $2 }

scope_head:
| SCOPE boption(IMPORT) attrs(uident_nq)
    { Typing.open_scope (floc $startpos $endpos) $3; $2 }

module_decl:
| scope_head module_decl* END
    { Typing.close_scope (floc $startpos($1) $endpos($1)) ~import:$1 }
| IMPORT uqualid
    { Typing.add_decl (floc $startpos $endpos) (Dimport($2)) }
| d = pure_decl | d = prog_decl | d = meta_decl
    { Typing.add_decl (floc $startpos $endpos) d }
| use_clone { () }

module_decl_parsing_only:
| scope_head_parsing_only module_decl_parsing_only* END
    { let loc,import,qid = $1 in (Dscope(loc,import,qid,$2))}
| IMPORT uqualid { (Dimport $2) }
| d = pure_decl | d = prog_decl | d = meta_decl { d }
| use_clone_parsing_only { $1 }

(* Do not open inside another module *)

mlw_module_no_decl:
| SCOPE | IMPORT | USE | CLONE | pure_decl | prog_decl | meta_decl
   { let loc = floc $startpos $endpos in
     Loc.errorm ~loc "trying to open a module inside another module" }
| mlw_module
   { $1 }

mlw_module_no_decl_parsing_only:
| SCOPE | IMPORT | USE | CLONE | pure_decl | prog_decl | meta_decl
   { let loc = floc $startpos $endpos in
     Loc.errorm ~loc "trying to open a module inside another module" }
| mlw_module_parsing_only
   { $1 }

module_decl_no_head:
| THEORY | MODULE
   { let loc = floc $startpos $endpos in
     Loc.errorm ~loc "trying to open a module inside another module" }
| module_decl
   { $1 }

module_decl_no_head_parsing_only:
| THEORY | MODULE
   { let loc = floc $startpos $endpos in
     Loc.errorm ~loc "trying to open a module inside another module" }
| module_decl_parsing_only

let () = Debug.set_debug_formatter escape_formatter

(* This is to be executed when scheduling ends *)
let ending c () =
  Debug.Stats.record_timing "gnatwhy3.run_vcs"
    (fun () -> C.remove_all_valid_ce_attempt c.Controller_itp.controller_session);
  Debug.Stats.record_timing "gnatwhy3.save_session" (fun () -> C.save_session c);
  Gnat_checks.iter (report_messages c);
  let s = Buffer.contents escape_buffer in
  if s <> "" then
    Gnat_report.add_warning s;
  Gnat_report.print_messages ();
  (* Dump profiling data (when compiled with profiling enabled) to file whose
     name is based on the processed .mlw file; otherwise profile data from
     several compilation would be written to a single gmon.out file and
     overwrite each other. When compiled with profiling disabled it has no
     visible effect. Note: we set the filename just before the program exit
     to not interfere with profiling of provers.
   *)
  let basename =
    Filename.chop_extension
      (Filename.basename Gnat_config.filename) in
  Unix.putenv "GMON_OUT_PREFIX" (basename ^ "_gnatwhy3_gmon.out")

let normal_handle_one_subp c subp =
   C.init_subp_vcs c subp;
   let s = c.Controller_itp.controller_session in
   Gnat_checks.iter_leaf_goals s subp (register_goal c)

(* save session on interrupt initiated by the user *)
let save_session_and_exit c signum =
  (* Ignore all SIGINT, SIGHUP and SIGTERM, which may be received when
     gnatprove is called in GNATStudio, so that the session file is always
     saved. Wrap in exception block as some signals are not supported on
     windows. *)
  begin try
    Sys.set_signal Sys.sigint Sys.Signal_ignore;
    Sys.set_signal Sys.sighup Sys.Signal_ignore;
    Sys.set_signal Sys.sigterm Sys.Signal_ignore;
  with Invalid_argument _ -> () end;
  C.save_session c;
  exit signum

 (* This is the main code. We read the file into the session if not already
    done, we apply the split_goal transformation when needed, and we schedule
    the first VC of all check. When done, we save the session.
 *)

let _ =
  if Gnat_config.debug then Debug.(set_flag (lookup_flag "gnat_ast"));
  Debug.set_flag Pinterp.debug_disable_builtin_mach;
  Debug.set_flag Debug.stats;
  List.iter Introduction.add_unique_prefix
    ["GP_Check:"; "GP_Pretty_Ada:"; "GP_Shape:"; "GP_Sloc:";
     "GP_Already_Proved"; "GP_Inline"; "GP_Inlined"];
  ( try
      let log = Sys.getenv "GNATWHY3LOG" in
      let out = open_out_gen [Open_text; Open_creat; Open_append] 0o666 log in
      let fmt = Format.formatter_of_out_channel out in
      Debug.set_debug_formatter fmt;
      Format.fprintf fmt "@.@.===== %s@." Gnat_config.filename;
      Loc.set_warning_hook (fun ?loc:_ line -> Format.fprintf fmt "%s@." line)
    with Not_found -> () );
  try
    let c = Debug.Stats.record_timing "gnatwhy3.init" Gnat_checks.init_cont in
    (* This has to be done after initialization of controller. Otherwise we
       don't have session. *)
    Sys.set_signal Sys.sigint (Sys.Signal_handle (save_session_and_exit c));
    begin match Gnat_config.proof_mode with
    | Gnat_config.Progressive
    | Gnat_config.Per_Path
    | Gnat_config.Per_Check ->
        Debug.Stats.record_timing "gnatwhy3.register_vcs"
         (fun () -> C.iter_subps c (normal_handle_one_subp c));
        if Gnat_config.replay then begin
          C.replay c (*;
          Gnat_checks.do_scheduled_jobs (fun _ _ -> ());*)
        end else begin
          Debug.Stats.record_timing "gnatwhy3.schedule_vcs"
           (fun () -> Gnat_checks.iter (handle_obj c));
        end;
     | Gnat_config.All_Split ->
        C.iter_subps c (all_split_subp c)
     | Gnat_config.No_WP ->
        (* we should never get here *)
        ()
    end;
    Gnat_scheduler.main_loop (ending c)
  with e when Debug.test_flag Debug.stack_trace -> raise e
  | Out_of_memory as e -> raise e
  | e ->
      let s = Pp.sprintf "%a.@." Exn_printer.exn_printer e in
      Gnat_util.abort_with_message ~internal:true s

let load_drivers c =
  let env = c.controller_env in
  let config = c.controller_config in
  let provers = Whyconf.get_provers config in
  let main = Whyconf.get_main config in
  Whyconf.Mprover.iter (fun _ p ->
      let d = Driver.load_driver_for_prover main env p in
      Whyconf.Hprover.add c.controller_provers p.Whyconf.prover (p,d))
    provers

let create_controller config env ses =
  let c =
    {
      controller_session = ses;
      controller_config = config;
      controller_env = env;
      controller_provers = Whyconf.Hprover.create 7;
      controller_strategies = Hstr.create 7;
      controller_running_proof_attempts = Hpan.create 17;
    }
  in
  load_drivers c;
  c

let reload_files ?(hard_reload=false) ?reparse_file_fun ~ignore_shapes (c : controller) =
  let old_ses = c.controller_session in
  if hard_reload then begin
    c.controller_env <- Env.create_env (Env.get_loadpath c.controller_env);
    Whyconf.Hprover.reset c.controller_provers;
    load_drivers c;
  end;
  c.controller_session <- empty_session ~from:old_ses (get_dir old_ses);
  (* FIXME: here we should compare [shape_version] with the version of shapes just loaded.
     OR: even better, this function has no reason to have a [shape_version] parameter
     and should always take the version from the file just loaded. *)
  match reparse_file_fun with
  | None ->
      merge_files ~ignore_shapes c.controller_env c.controller_session old_ses
  | Some reparse_file_fun ->
      merge_files_gen ~ignore_shapes ~reparse_file_fun c.controller_env c.controller_session old_ses

  else nres


let build_prover_call spa =
  let c = spa.spa_contr in
  let limits = spa.spa_limits in
  let (config_pr,driver) = Hprover.find c.controller_provers spa.spa_pr in
  let with_steps =
    Call_provers.(limits.limit_steps > empty_limits.limit_steps) in
  let command =
    Whyconf.get_complete_command config_pr ~with_steps in
  match Session_itp.get_task c.controller_session spa.spa_id with
  | exception Not_found (* goal has no task, it is detached *) ->
    spa.spa_callback Detached
  | task ->
    Debug.dprintf debug_sched "[build_prover_call] Script file = %a@."
                  (Pp.print_option Pp.string) spa.spa_pr_scr;
    let inplace = config_pr.Whyconf.in_place in
    let interactive = config_pr.Whyconf.interactive in
    let main = Whyconf.get_main c.controller_config in
    try
      let call = Driver.prove_task ?old:spa.spa_pr_scr ~inplace ~command
          ~limits ~interactive ~config:main driver task in
      let pa =
        { tp_id       = spa.spa_id;
          tp_callback = spa.spa_callback;
          tp_started  = false;
          tp_call     = call;
          tp_ores     = spa.spa_ores } in
      Hashtbl.replace prover_tasks_in_progress call pa

let update_task = let ht = Hint.create 5 in fun drv ->
    let update task0 =
      (* add requested theorie *)
      let task0 = Mid.fold (fun _ (th,th') task ->
          let tdcs = Task.find_clone_tds task0 th in
          HStdecl.fold (fun tdc task -> match tdc.td_node with
              | Use _ -> Task.use_export task th'
              | Clone (_,_) ->
                  (* We do nothing in case of clone *)
                  task
              | _ -> assert false
            ) tdcs task
        ) drv.drv_thuse task0
      in
      (* apply metas *)
      let task0 = Mid.fold (fun _ (th,tdms) task ->
          let tdcs = Task.find_clone_tds task0 th in
          HStdecl.fold (fun tdc task ->
              Stdecl.fold (fun tdm task -> match tdc.td_node with
                  | Use _ -> add_tdecl task tdm
                  | Clone (_,sm) ->
                      let tdm = Theory.clone_meta tdm th sm in
                      Opt.fold add_tdecl task tdm
                  | _ -> assert false
                ) tdms task
            ) tdcs task
        ) drv.drv_meta task0
      in
      task0
    in
  function
  | Some {task_decl = {td_node = Decl {d_node = Dprop (Pgoal,_,_)}} as goal;
          task_prev = task} ->
      (* we cannot add metas nor memoize after goal *)
      let update = try Hint.find ht drv.drv_tag with Not_found ->
        let upd = Trans.store update in
        Hint.add ht drv.drv_tag upd; upd in
      let task = Trans.apply update task in
      add_tdecl task goal
    | task -> update task

(* Apply driver's transformations to the task *)
let prepare_task drv task =
  let lookup_transform t =
    lookup_transform t drv.drv_env, t in
  let transl = List.map lookup_transform drv.drv_transform in
  let apply task (tr,name) =
    let task =
      Debug.Stats.record_timing ("gnatwhy3.transformations." ^ name)
        (fun () -> Trans.apply tr task) in
    Debug.dprintf driver_debug "Task after transformation: %s\n%a@."
      name Pretty.print_task task;
    task
  in
  Debug.dprintf driver_debug "Task before driver's transformation\n%a@."
    Pretty.print_task task;
  let task = update_task drv task in
  Debug.dprintf driver_debug "Task after update\n%a@."
    Pretty.print_task task;
  List.fold_left apply task transl

let print_task_prepared ?old drv fmt task =
  let p = match drv.drv_printer with
    | None -> raise NoPrinter
    | Some p -> p
  in
  let printer_args = Printer.{
      env           = drv.drv_env;
      prelude       = drv.drv_prelude;
      th_prelude    = drv.drv_thprelude;
      blacklist     = drv.drv_blacklist;
      printing_info = ref None;
    } in
  fprintf fmt "@[%a@]@?" (lookup_printer p ?old printer_args) task;
  Option.value ~default:(default_printing_info printer_args.env) !(printer_args.printing_info)

let print_task ?old drv fmt task =
  let task = prepare_task drv task in
  let _ = print_task_prepared ?old drv fmt task in

  fun () ->
    incr x;
    !x

type save_data = {
  vc_file         : string;
  inplace         : bool;
  limits          : resource_limits;
  res_parser      : prover_result_parser;
  get_model       : Printer.printing_info option;
}

let saved_data : (int, save_data) Hashtbl.t = Hashtbl.create 17

open Prove_client

let handle_answer answer =
  match answer with
  | Finished { id; time; timeout; out_file; exit_code } ->
      let save = Hashtbl.find saved_data id in
      Hashtbl.remove saved_data id;
      let keep_vcs =
        try let flag = Debug.lookup_flag "keep_vcs" in Debug.test_flag flag with
        | _ -> false
      in
      if Debug.test_noflag debug && not keep_vcs then begin
        Sys.remove save.vc_file;
        if save.inplace then Sys.rename (backup_file save.vc_file) save.vc_file
      end;
      let ans = parse_prover_run save.res_parser timeout time out_file exit_code
          save.limits save.get_model in
      id, Some ans
  | Started id ->
      id, None

let wait_for_server_result ~blocking =
  List.map handle_answer (read_answers ~blocking)

type server_id = int
type editor_id = int

type prover_call =
  | ServerCall of server_id
  | EditorCall of int

let call_on_file
      ~config ~command ~limits ~res_parser ~get_model ?(inplace=false) fin =
  let id = gen_id () in
  let cmd, use_stdin, on_timelimit =
    actualcommand ~cleanup:true ~inplace ~config command limits fin in
  let save = {
    vc_file         = fin;
    inplace         = inplace;
    limits          = limits;
    res_parser      = res_parser;
    get_model       = get_model;
  } in
  Hashtbl.add saved_data id save;
  let limits = adapt_limits limits on_timelimit in

  Debug.Args.set_flags_selected ~silent:true ();
  let config = init_config ~extra_config:(!opt_extra) !opt_config in
  (* Set option if they are false *)
  let apply_not_default f o b = if !o then b else f !o b in
  let config = apply_not_default set_stdlib opt_stdlib config in
  let config = apply_not_default set_load_default_plugins opt_load_default_plugins config in
  let main = get_main config in
  let lp = List.rev_append !opt_loadpath (loadpath main) in
  let config = set_main config (set_loadpath main lp) in
  load_plugins main;
  Debug.Args.set_flags_selected ();
  Loc.Args.set_flags_selected ();
  if Debug.Args.option_list () then exit 0;
  if Loc.Args.option_list () then exit 0;
  config, Env.create_env lp

let initialize ?(extra_help="") options default usage =
  let options = all_options options usage extra_help in
  Getopt.parse_all ~i:!first_arg options default Sys.argv;
  complete_initialization ()

